        'Durum eleştirisi kimin konuşabileceğini; içerik eleştirisi ne söylendiğini sorar.',
    level: 'C2',
    audioPath: 'audio/c2/c2_463.mp3',
  ),
  Sentence(
    id: 'c2_464',
    englishText: 'Where ends are plural, ranking them is already a moral act.',
