        'Güven ahlaki olduğu kadar epistemikse ihanet bilgi ağlarına zarar verir.',
    level: 'C2',
    audioPath: 'audio/c2/c2_466.mp3',
  ),
  Sentence(
    id: 'c2_467',
    englishText:
        'The demand for purity in politics often trades effectiveness for self-regard.',
