        'Siyasette saflık talebi çoğu zaman etkinliği kendini beğenmişlikle takas eder.',
    level: 'C2',
    audioPath: 'audio/c2/c2_467.mp3',
  ),
  Sentence(
    id: 'c2_468',
    englishText:
        'A thought experiment clarifies intuition only if the imagined world shares our constraints.',
