        'Kamusal akıl kısıtı argümanları süzer; ortak sonuçlar icat etmez.',
    level: 'C2',
    audioPath: 'audio/c2/c2_471.mp3',
  ),
  Sentence(
    id: 'c2_472',
    englishText:
        'If harm is comparative, baseline selection silently decides the verdict.',
