    level: 'C2',
    audioPath: 'audio/c2/c2_473.mp3',
  ),
  Sentence(
    id: 'c2_474',
    englishText:
        'Where metaphors govern thought, changing metaphors can change what seems possible.',
    turkishText:
        'Metaforlar düşünceyi yönetiyorsa metafor değiştirmek mümkün görüneni değiştirebilir.',
    level: 'C2',
    audioPath: 'audio/c2/c2_474.mp3',
  ),
  Sentence(
    id: 'c2_475',
    englishText:
        'A residual category named \'other\' often hides the cases that challenge the taxonomy.',
