        'Sonuçlardan argüman yalnızca korkulan manşet değil nedensel model ister.',
    level: 'C2',
    audioPath: 'audio/c2/c2_477.mp3',
  ),
  Sentence(
    id: 'c2_478',
    englishText:
        'A thin liberalism that ignores power will be captured by whoever already holds it.',
