        'İktidarı yok sayan ince liberalizm, onu zaten tutanın eline geçer.',
    level: 'C2',
    audioPath: 'audio/c2/c2_478.mp3',
  ),
  Sentence(
    id: 'c2_479',
    englishText:
        'If meaning depends on background practices, radical doubt is socially parasitic.',
    turkishText:
        'Anlam arka plan pratiklerine bağlıysa radikal şüphe toplumsal olarak asalaktır.',
    level: 'C2',
    audioPath: 'audio/c2/c2_479.mp3',
  ),
  Sentence(
    id: 'c2_480',
    englishText:
        'The distinction between reform and revolution is often one of tempo and risk appetite.',
