        'Reform ile devrim ayrımı çoğu zaman tempo ve risk iştahı ayrımıdır.',
    level: 'C2',
    audioPath: 'audio/c2/c2_480.mp3',
  ),
  Sentence(
    id: 'c2_481',
    englishText:
        'A coherentism that never touches the world becomes a closed aesthetic.',
    turkishText:
        'Dünyaya hiç değmeyen bağdaşımcılık kapalı bir estetiğe dönüşür.',
    level: 'C2',
    audioPath: 'audio/c2/c2_481.mp3',
  ),
  Sentence(
    id: 'c2_482',
    englishText:
        'If the self is relational, authenticity cannot mean isolation from others\' claims.',
