        'Benlik ilişkisel ise özgünlük başkalarının iddialarından yalıtılma demek olamaz.',
    level: 'C2',
    audioPath: 'audio/c2/c2_482.mp3',
  ),
  Sentence(
    id: 'c2_483',
    englishText:
        'The problem of dirty hands asks whether political success can require moral residue.',
