        'Kirli eller sorunu siyasi başarının ahlaki kalıntı gerektirip gerektirmediğini sorar.',
    level: 'C2',
    audioPath: 'audio/c2/c2_483.mp3',
  ),
  Sentence(
    id: 'c2_484',
    englishText:
        'A definition that settles a dispute by fiat has argued by vocabulary, not by reason.',
    turkishText:
        'Anlaşmazlığı buyrukla çözen tanım akılla değil sözlükle tartışmıştır.',
    level: 'C2',
    audioPath: 'audio/c2/c2_484.mp3',
  ),
  Sentence(
    id: 'c2_485',
    englishText:
        'If equality before the law ignores unequal access, formality becomes a mask.',
