        'Yasa önünde eşitlik eşitsiz erişimi yok sayarsa biçimsellik maskeye dönüşür.',
    level: 'C2',
    audioPath: 'audio/c2/c2_485.mp3',
  ),
  Sentence(
    id: 'c2_486',
